   109→export const action = async ({ request }: ActionFunctionArgs) => {
   110→  const { session, admin } = await authenticate.admin(request);
   111→  const shop = session.shop;
   112→  const formData = await request.formData();
   113→  const intent = formData.get("intent");
   114→
   115→  if (intent === "save") {
   116→    const data = {
   117→      position: String(formData.get("position") || "inline"),
   118→      primaryColor: String(formData.get("primaryColor") || "#008060"),
   119→      successColor: String(formData.get("successColor") || "#008060"),
   120→      errorColor: String(formData.get("errorColor") || "#D72C0D"),
   121→      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
   122→      textColor: String(formData.get("textColor") || "#202223"),
   123→      heading: String(formData.get("heading") || "Check Delivery Availability"),
   124→      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
   125→      buttonText: String(formData.get("buttonText") || "Check"),
   126→      successMessage: String(
   127→        formData.get("successMessage") ||
   128→          "Great news! We deliver to your area.",
   129→      ),
   130→      errorMessage: String(
   131→        formData.get("errorMessage") ||
   132→          "Sorry, we don't deliver to this area yet.",
   133→      ),
   134→      notFoundMessage: String(
   135→        formData.get("notFoundMessage") ||
   136→          "This zip code was not found in our system.",
   137→      ),
   138→      showEta: formData.get("showEta") === "true",
   139→      showZone: formData.get("showZone") === "true",
   140→      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
   141→      borderRadius: String(formData.get("borderRadius") || "8"),
   142→      customCss: String(formData.get("customCss") || "") || null,
   143→    };
   144→
   145→    await db.widgetConfig.upsert({
   146→      where: { shop },
   147→      create: { shop, ...data },
   148→      update: data,
   149→    });
   150→
   151→    // Sync to shop metafield so storefront reads config without API call
   152→    await syncConfigMetafield(admin, data);
   153→
   154→    return { success: true };
   155→  }
   156→
   157→  if (intent === "reset") {
   158→    const resetData = {
   159→      position: "inline",
   160→      primaryColor: "#008060",
   161→      successColor: "#008060",
   162→      errorColor: "#D72C0D",
   163→      backgroundColor: "#FFFFFF",
   164→      textColor: "#202223",
   165→      heading: "Check Delivery Availability",
   166→      placeholder: "Enter your zip code",
   167→      buttonText: "Check",
   168→      successMessage: "Great news! We deliver to your area.",
   169→      errorMessage: "Sorry, we don't deliver to this area yet.",
   170→      notFoundMessage: "This zip code was not found in our system.",
   171→      showEta: true,
   172→      showZone: false,
   173→      showWaitlistOnFailure: false,
   174→      borderRadius: "8",
   175→      customCss: null,
   176→    };
   177→
   178→    await db.widgetConfig.upsert({
   179→      where: { shop },
   180→      create: { shop },
   181→      update: resetData,
   182→    });
   183→
   184→    // Sync reset config to metafield
   185→    await syncConfigMetafield(admin, resetData);
   186→
   187→    return { success: true, action: "reset" };
   188→  }
   189→
   190→  return null;
   191→};
   192→
   193→type WidgetConfig = {
   194→  position: string;
   195→  primaryColor: string;
   196→  successColor: string;
   197→  errorColor: string;
   198→  backgroundColor: string;
   199→  textColor: string;
   200→  heading: string;
   201→  placeholder: string;
   202→  buttonText: string;
   203→  successMessage: string;
   204→  errorMessage: string;
   205→  notFoundMessage: string;
   206→  showEta: boolean;
   207→  showZone: boolean;
   208→  showWaitlistOnFailure: boolean;
   209→  borderRadius: string;
   210→  customCss: string | null;
   211→};
   212→
   213→// ── Default widget configuration values ─────────────────────────────────────
   214→const DEFAULTS = {
   215→  position: "inline",
   216→  primaryColor: "#008060",
   217→  successColor: "#008060",
   218→  errorColor: "#D72C0D",
   219→  backgroundColor: "#FFFFFF",
   220→  textColor: "#202223",
   221→  heading: "Check Delivery Availability",
   222→  placeholder: "Enter your zip code",
   223→  buttonText: "Check",
   224→  successMessage: "Great news! We deliver to your area.",
   225→  errorMessage: "Sorry, we don't deliver to this area yet.",
   226→  notFoundMessage: "This zip code was not found in our system.",
   227→  showEta: true,
   228→  showZone: false,
   229→  showWaitlistOnFailure: false,
   230→  borderRadius: "8",
   231→  customCss: "",
   232→};
   233→
   234→// ── CSS generator — mirrors the Liquid block CSS exactly ────────────────────
   235→function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
   236→  const rad = cfg.borderRadius + "px";
   237→  return (
   238→    "#" + wid + "{" +
   239→      "background:" + cfg.backgroundColor + ";" +
   240→      "color:" + cfg.textColor + ";" +
   241→      "border-radius:" + rad + ";" +
   242→      "padding:24px;" +
   243→      "border:1px solid #e1e3e5;" +
   244→      "max-width:400px;" +
   245→      "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
   246→      "box-sizing:border-box;" +
   247→    "}" +
   248→    "#" + wid + " *{box-sizing:border-box}" +
   249→    "#" + wid + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
   250→    "#" + wid + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
   251→    "#" + wid + " .zcc-input{" +
   252→      "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
   253→      "border-radius:" + rad + ";font-size:14px;outline:none;" +
   254→      "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
   255→    "}" +
   256→    "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
   257→    "#" + wid + " .zcc-btn{" +
   258→      "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
   259→      "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
   260→      "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
   261→    "}" +
   262→    "#" + wid + " .zcc-btn:hover{opacity:.9}" +
   263→    "#" + wid + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
   264→    "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
   265→    "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
   266→    "#" + wid + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
   267→    "#" + wid + " .zcc-wl{margin-top:10px}" +
   268→    "#" + wid + " .zcc-wl-input{" +
   269→      "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
   270→      "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
   271→    "}" +
   272→    "#" + wid + " .zcc-wl-btn{" +
   273→      "background:" + cfg.errorColor + ";color:#fff;border:none;" +
   274→      "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
   275→      "cursor:pointer;width:100%;font-weight:600" +
   276→    "}" +
   277→    // Sanitize customCss: strip </style> close tags to prevent injection into <style> elements
   278→    (cfg.customCss ? cfg.customCss.replace(/<\/style>/gi, "") : "")
   279→  );
   280→}
   281→
   282→// ── Live Preview component (defined outside WidgetPage to avoid remounting) ─
   283→function WidgetPreview({
   284→  cfg,
   285→  previewState,
   286→}: {
   287→  cfg: WidgetConfig;
   288→  previewState: "idle" | "success" | "error" | "notfound";
   289→}) {
   290→  const wid = "zcc-admin-preview";
   291→  const css = buildWidgetCss(wid, cfg);
   292→
   293→  const resultClass =
   294→    previewState === "success" ? "ok" :
   295→    (previewState === "error" || previewState === "notfound") ? "fail" : "";
   296→
   297→  const resultMessage =
   298→    previewState === "success" ? cfg.successMessage :
   299→    previewState === "error" ? cfg.errorMessage :
   300→    previewState === "notfound" ? cfg.notFoundMessage : null;
   301→
   302→  const widgetHtml = (
   303→    <div id={wid}>
   304→      <p className="zcc-heading">{cfg.heading}</p>
   305→      <div className="zcc-row">
   306→        <input
   307→          className="zcc-input"
   308→          type="text"
   309→          placeholder={cfg.placeholder}
   310→          readOnly
   311→        />
   312→        <button className="zcc-btn" type="button">
   313→          {cfg.buttonText}
   314→        </button>
   315→      </div>
   316→      {resultMessage && (
   317→        <div className={`zcc-result ${resultClass}`}>
   318→          {resultMessage}
   319→          {previewState === "success" && cfg.showEta && (
   320→            <div className="zcc-meta">Estimated delivery: 2–3 business days</div>
   321→          )}
   322→          {previewState === "success" && cfg.showZone && (
   323→            <div className="zcc-meta">Zone: Manhattan</div>
   324→          )}
   325→          {(previewState === "error" || previewState === "notfound") &&
   326→            cfg.showWaitlistOnFailure && (
   327→              <div className="zcc-wl">
   328→                <input
   329→                  className="zcc-wl-input"
   330→                  type="email"
   331→                  placeholder="Enter email to join waitlist"
   332→                  readOnly
   333→                />
   334→                <button className="zcc-wl-btn" type="button">
   335→                  Join Waitlist
   336→                </button>
   337→              </div>
   338→            )}
   339→        </div>
   340→      )}
   341→    </div>
   342→  );
   343→
   344→  // Floating position: show mock fixed button + collapsible panel concept
   345→  if (cfg.position === "floating") {
   346→    return (
   347→      <>
   348→        {/* eslint-disable-next-line react/no-danger */}
   349→        <style dangerouslySetInnerHTML={{ __html: css }} />
   350→        <div
   351→          style={{
   352→            position: "relative",
