   201→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   202→    var inp = document.getElementById(wid + "-inp");
   203→    var btn = document.getElementById(wid + "-btn");
   204→    var res = document.getElementById(wid + "-res");
   205→    var btnLabel = cfg.buttonText;
   206→    if (!inp || !btn || !res) return;
   207→
   208→    function checkZip() {
   209→      var zip = inp.value.trim();
   210→      if (!zip) { inp.focus(); return; }
   211→
   212→      btn.disabled = true;
   213→      btn.textContent = "\u2026";
   214→      res.innerHTML = "";
   215→
   216→      fetch(
   217→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   218→          "&zip=" + encodeURIComponent(zip)
   219→      )
   220→        .then(function (r) { return r.json(); })
   221→        .then(function (data) {
   222→          btn.disabled = false;
   223→          btn.textContent = btnLabel;
   224→
   225→          if (data.allowed) {
   226→            var html = '<div class="zcc-result ok">' + esc(data.message);
   227→            if (cfg.showEta && data.eta) {
   228→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   229→            }
   230→            if (cfg.showZone && data.zone) {
   231→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   232→            }
   233→            if (data.daysOfWeek) {
   234→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   235→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
   236→            }
   237→            if (data.cutoffTime) {
   238→              var parts = data.cutoffTime.split(':');
   239→              var hr = parseInt(parts[0], 10);
   240→              var min = parts[1] || '00';
   241→              var ampm = hr >= 12 ? 'PM' : 'AM';
   242→              var hr12 = hr % 12 || 12;
   243→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
   244→            }
   245→            html += "</div>";
   246→            res.innerHTML = html;
   247→          } else {
   248→            var html = '<div class="zcc-result fail">' + esc(data.message);
   249→            if (cfg.showWaitlistOnFailure) {
   250→              html +=
   251→                '<div class="zcc-wl">' +
   252→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   253→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   254→                "</div>";
