   257→            res.innerHTML = html;
   258→
   259→            if (cfg.showWaitlistOnFailure) {
   260→              var wBtn = document.getElementById(wid + "-wl-btn");
   261→              if (wBtn) {
   262→                wBtn.addEventListener("click", function () {
   263→                  var emailEl = document.getElementById(wid + "-wl-email");
   264→                  var email = emailEl ? emailEl.value.trim() : "";
